node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {sanitizeSvg,renderDodManifest,sha256Hex} from './tools/render-dod-manifest.mjs';
const source=JSON.parse(readFileSync('docs/plans/2026-09-12-bearing-delivery-lifecycle-alignment/implementation.json','utf8'));
function render(svg){const d=structuredClone(source);d.dod_manifest.models=[{id:'S8-FIXTURE',required:true,selected:true,render_status:'READY',digest:sha256Hex(svg),view:{format:'svg',inline:svg}}];delete d.dod_manifest.closeout.model_views;return renderDodManifest(d).html;}
const svg='<svg xmlns="http://www.w3.org/2000/svg"><style>#s8, #s9 { display: none !important; }</style><text x="0" y="20">Model</text></svg>';
const html=render(svg);assert.match(html,/\.dod-svg-[0-9a-f]+ #s8,\s*\.dod-svg-[0-9a-f]+ #s9/);assert.doesNotMatch(html,/<style>#s8,/);assert.match(html,/id="s8"/);assert.match(html,/id="s9"/);
console.log('S7-003 PASS: complete in-memory rendering scopes both selectors and retains risk/authority sections.');
const escaped='<svg xmlns="http://www.w3.org/2000/svg"><style>@im\\70ort "https://example.invalid/model.css";</style></svg>';
assert.throws(()=>sanitizeSvg(escaped),e=>e.code==='UNSAFE_ASSET');assert.throws(()=>render(escaped),e=>e.code==='UNSAFE_ASSET');assert.throws(()=>sanitizeSvg('<svg><rect style="fill: u\\72l(https://example.invalid/x)" /></svg>'),e=>e.code==='UNSAFE_ASSET');
console.log('S7-004 PASS: escaped import rejected by sanitizer and complete render; escaped external style URL rejected. Expected negative-test behavior; no URL contacted.');
const safe=render('<svg xmlns="http://www.w3.org/2000/svg"><style>text { fill: #0e5c66; }</style><text x="0" y="20">Model</text></svg>');assert.match(safe,/text\s*\{\s*fill:\s*#0e5c66/);
console.log('S7-003 safe-style control PASS; all rendering remained in memory.');
JS
